import{_ as o,o as e,c as r,a2 as a}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"会议模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/meeting.md","filePath":"zh/guide/meeting.md","lastUpdated":1793129134000}'),l={name:"zh/guide/meeting.md"};function n(s,t,i,g,d,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="会议模式" tabindex="-1">会议模式 <a class="header-anchor" href="#会议模式" aria-label="Permalink to &quot;会议模式&quot;">​</a></h1><p>本页说明 MeetCue 如何跟随一场实时会议：什么时候出提示、连续几个问题如何处理，以及怎样看懂面板。</p><h2 id="开始与暂停拾取" tabindex="-1">开始与暂停拾取 <a class="header-anchor" href="#开始与暂停拾取" aria-label="Permalink to &quot;开始与暂停拾取&quot;">​</a></h2><p>按 <code>Ctrl+Alt+Space</code>，或点击面板上的 <strong>开始</strong>。状态点变绿，计时开始。再按一次即暂停；暂停期间不会向任何供应商发送数据。</p><p>也可以在托盘图标菜单中开始或暂停。</p><h2 id="从问题到提示" tabindex="-1">从问题到提示 <a class="header-anchor" href="#从问题到提示" aria-label="Permalink to &quot;从问题到提示&quot;">​</a></h2><ol><li><strong>识别</strong>：两路音频实时发送给语音识别供应商。只发送含有语音的部分，静音会跳过（只保留很短的保活信号）。</li><li><strong>检测</strong>：其他与会者说完一句话后，检测模型判断这是不是问给你的问题。你自己麦克风里的话永远不会被当作问题。</li><li><strong>提示</strong>：对于问题，要点模型生成三到五条编号要点和一段简短的示例回答。要点边生成边逐条显示。</li></ol><p>开启 <strong>提前触发</strong>（<strong>设置 › 提示</strong>）后，说话人一停顿，MeetCue 就开始生成，而不必等这句话正式结束。如果对方继续说下去、问题明显变了，提前发出的请求会被取消并重新生成。大多数问题因此能快几百毫秒。</p><p>开启 <strong>边判断问题边生成提示</strong>（同在 <strong>设置 › 提示</strong>，默认开启）后，问题判断和提示生成同时开始，而不是先后进行。只有判断确认是问题时才会显示提示，面板上看不出区别，但第一条要点通常能早一秒左右出现。看起来像问题、实际不是的句子，会多花一次用不上的提示请求。</p><h2 id="看懂面板" tabindex="-1">看懂面板 <a class="header-anchor" href="#看懂面板" aria-label="Permalink to &quot;看懂面板&quot;">​</a></h2><p>完整面板自上而下依次是：</p><ol><li><strong>标题栏</strong>：状态、已用时间、暂停、置顶，以及切换到迷你条。</li><li><strong>音源</strong>：麦克风和系统声音各一个电平条。面板一显示电平条就会跳动，不必先开始，方便确认 MeetCue 能听到你。开始之前不会向任何供应商发送内容。</li><li><strong>问题队列</strong>：上一问、当前、下一问及其状态。点击卡片即可滚动到对应问题。</li><li><strong>对话</strong>：每个问题一个聊天块。正在回答的问题始终在最上方，其后是排队等待的问题，再往下是较早的问题（新的在前）。点击灰色问题原文可以看到前后几句转写以及识别依据。<strong>查看全文</strong> 展开示例回答。</li><li><strong>底栏</strong>：快捷键提示和最近一次提示的延迟。</li></ol><p><strong>迷你条</strong>（<code>Ctrl+Alt+H</code>）只显示当前问题、进度、下一条要讲的要点（大字）以及排队的问题数。</p><p>为了让视线靠近摄像头，可以用 <code>Ctrl+Alt+Shift</code> 加方向键把面板移到摄像头正下方。参见<a href="/meetcue/zh/guide/shortcuts#move-the-panel">移动面板</a>。</p><h2 id="让面板不挡事" tabindex="-1">让面板不挡事 <a class="header-anchor" href="#让面板不挡事" aria-label="Permalink to &quot;让面板不挡事&quot;">​</a></h2><p>面板不应挡住会议的 <strong>加入</strong> 按钮、其他参会者或共享的屏幕。以下操作都可以用触控板完成：</p><ul><li><strong>从任意位置拖动。</strong> 按住面板的任意空白处（不只是标题栏）即可拖动。触控板上轻点两下再拖动同样可以移动。</li><li>标题栏中的 <strong>移动</strong> 提供一键操作： <ul><li><strong>贴靠到边缘或角落</strong>：八个方向箭头把面板放到屏幕对应的边缘，并避开任务栏。连接多个屏幕时，中间的按钮把面板移到下一个屏幕。</li><li><strong>已保存的位置</strong>：最多保存三个位置，各自记住大小和形态，用 <code>Ctrl+Alt+Shift+1</code>、<code>2</code>、<code>3</code> 返回。参见<a href="/meetcue/zh/guide/shortcuts#saved-spots">保存的位置</a>。</li><li><strong>大小</strong>：窄、标准或宽，高度为屏幕的三分之一、一半或全高。也可以直接拖动面板边缘，大小会被记住。</li><li><strong>不透明度</strong> 和 <strong>文字</strong> 大小，让更小、半透明的面板依然清晰可读。</li><li><strong>隐藏 6 秒</strong>（<code>Ctrl+Alt+Shift+P</code>），用来点击面板后面的东西。</li><li><strong>鼠标点击穿透</strong>（<code>Ctrl+Alt+Shift+T</code>）：面板变淡，鼠标直接作用于后面的窗口。再按一次快捷键或使用托盘菜单即可关闭。</li></ul></li></ul><p>所有窗口的字体，以及面板的文字大小和不透明度，也可以在 <strong>设置 › 通用</strong> 中设置。</p><h2 id="已讲要点打勾" tabindex="-1">已讲要点打勾 <a class="header-anchor" href="#已讲要点打勾" aria-label="Permalink to &quot;已讲要点打勾&quot;">​</a></h2><p>开启 <strong>跟踪已讲要点</strong> 后，MeetCue 会把你说的话与要点对比。讲到的要点打上绿色对勾，下一条未讲的要点标为 <strong>接下来</strong>。你还在说话时要点就会打勾，不必等你停顿。如果某条要点勾错了或漏勾了，点击它即可打勾或取消，之后 MeetCue 会保持你的设置。英文按单词匹配（单复数和时态视为同一个词），中文按相邻两字匹配，所以换个说法讲到也能识别。</p><p>如果你用外放而不是耳机，麦克风也会录到其他与会者的声音。MeetCue 会忽略与刚刚播放内容高度相似的麦克风文字，避免别人的话把你的要点勾掉。</p><h2 id="同时出现多个问题" tabindex="-1">同时出现多个问题 <a class="header-anchor" href="#同时出现多个问题" aria-label="Permalink to &quot;同时出现多个问题&quot;">​</a></h2><ul><li><strong>插话自动排队</strong>（默认开启）：你正在回答时被问到的新问题会排在 <strong>下一问</strong>。你答完之后，它自动成为当前问题。</li><li>你没有在说话时出现的新问题会替换当前问题，原问题移到 <strong>上一问</strong>。</li><li>用 <code>Ctrl+Alt+[</code> 和 <code>Ctrl+Alt+]</code> 在问题间切换，用 <code>Ctrl+Alt+Enter</code> 把当前问题标为已答。</li></ul><p>只有在你开口回答并停下之后，问题才算已答；开口前的沉默不会让问题被提前归档。</p><h2 id="共享屏幕时隐藏面板" tabindex="-1">共享屏幕时隐藏面板 <a class="header-anchor" href="#共享屏幕时隐藏面板" aria-label="Permalink to &quot;共享屏幕时隐藏面板&quot;">​</a></h2><p><strong>共享屏幕时隐藏面板</strong> 默认开启。Teams、Zoom、浏览器屏幕共享和大多数录屏工具会拍到面板后面的内容，而不是面板本身。</p><div class="warning custom-block"><p class="custom-block-title">并非绝对</p><p>部分录制方式和外接采集设备仍可能拍到面板。依赖这项功能之前，请先用你的会议软件实际测试。</p></div><h2 id="会议中的费用" tabindex="-1">会议中的费用 <a class="header-anchor" href="#会议中的费用" aria-label="Permalink to &quot;会议中的费用&quot;">​</a></h2><p>每次调用的用量都会记录，并按下载的价格表折算；没有价格的模型只计用量、不计费用。<strong>设置 › 供应商与费用</strong> 显示本月按供应商分列的用量。可以设置单次会议和每月预算：用到 80% 时提醒；到 100% 时按你的选择只提醒、暂停要点生成或结束会话。</p>',29)])])}const u=o(l,[["render",n]]);export{p as __pageData,u as default};
